INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 25, 'theory', 'Quiz: collections');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 0, 'Which collection suits a queue with adding at the end and taking from the front?', '["VecDeque", "Vec", "BinaryHeap", "HashSet"]', 0, 'VecDeque is a ring buffer: push_back and pop_front in O(1). Taking from the front of a Vec is O(n).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 1, 'How do you get a min-heap out of BinaryHeap?', '["BinaryHeap::min()", "call sort() on the heap", "you can''t: the heap is always a max-heap", "wrap the values in Reverse"]', 3, 'BinaryHeap<Reverse<T>> returns the smallest first.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 2, 'What does swap_remove do on a Vec?', '["removes the element and shifts the tail", "swaps two elements", "removes the element in O(1) by putting the last one in its place", "returns None"]', 2, 'swap_remove does not preserve order, but it costs O(1).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 3, 'When should you prefer BTreeMap over HashMap?', '["always, it is faster", "when you need key order and range queries", "when the keys are numbers", "when memory is not limited"]', 1, 'BTreeMap traverses keys in ascending order and offers range, first_key_value, pop_first.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 4, 'Why do the docs advise Vec and VecDeque instead of LinkedList?', '["a list does not support iterators", "a list cannot store numbers", "a list has no push method", "list nodes are scattered over the heap — many cache misses"]', 3, 'Because of data locality, Vec and VecDeque are faster in practice even where the list has better asymptotics.');
